<?php
require __DIR__.'/app/bootstrap.php';
$u=require_any_permission(['attendance.view','attendance.manage','workforce.view','payroll.view']);$d=db_load();
function ac_branch(array $d,$id): string {foreach($d['branches']??[] as $b)if((int)($b['id']??0)===(int)$id)return (string)($b['code']??'').' · '.(string)($b['name']??'');return 'ไม่ระบุสาขา';}
function ac_employee(array $d,$id): array {foreach($d['employees']??[] as $e)if((int)($e['id']??0)===(int)$id)return $e;return ['id'=>(int)$id,'code'=>'EMP#'.$id,'name'=>'ไม่พบ Employee','position'=>'other'];}
function ac_hm($value): string {if(!$value)return '—';$ts=strtotime((string)$value);return $ts?date('H:i:s',$ts):'—';}
$employeeId=(int)($_GET['employee_id']??0);$branchId=(int)($_GET['branch_id']??0);$position=(string)($_GET['position']??'');$from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-d'));
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');if($from>$to){$t=$from;$from=$to;$to=$t;}
$rows=[];foreach($d['attendance']??[] as $a){if(empty($a['check_in']))continue;$dt=substr((string)$a['check_in'],0,10);if($dt<$from||$dt>$to)continue;$eid=(int)($a['employee_id']??0);if($employeeId&&$eid!==$employeeId)continue;if($branchId&&(int)($a['branch_id']??0)!==$branchId)continue;$emp=ac_employee($d,$eid);if($position!==''&&(string)($emp['position']??'')!==$position)continue;$a['_employee']=$emp;$rows[]=$a;}
usort($rows,function($a,$b){return strcmp((string)($b['check_in']??''),(string)($a['check_in']??''));});
$employees=array_values(array_filter($d['employees']??[],function($e){return !empty($e['active']);}));usort($employees,function($a,$b){return strcmp((string)$a['code'],(string)$b['code']);});
$positions=[];foreach($employees as $e){$p=(string)($e['position']??'staff');$positions[$p]=workforce_position_label($p);}asort($positions);
$total=count($rows);$withIn=count(array_filter($rows,function($a){return !empty($a['checkin_evidence']);}));$withOut=count(array_filter($rows,function($a){return !empty($a['checkout_evidence']);}));$open=count(array_filter($rows,function($a){return empty($a['check_out']);}));
